"""Document the weak-port diagnosis, unfitted correction and independent checks."""
import html,json,shutil,sys
from pathlib import Path
from analyze_dielectric3d import read

def pc(v):return 'null' if v is None else f'{v*100:.4f}%'
def table(headers,rows):return '<table><tr>'+''.join('<th>'+html.escape(str(v))+'</th>' for v in headers)+'</tr>'+''.join('<tr>'+''.join('<td>'+html.escape(str(v))+'</td>' for v in row)+'</tr>' for row in rows)+'</table>'

def main(root):
    w=root/'work/d3weak';out=root/'outputs/differt-bridge/examples/dielectric3d_weak';out.mkdir(parents=True,exist_ok=True);a=read(w/'analysis.json');assert a['status']=='passed';weak=a['weak'];probes=read(w/'probe_analysis.json');diagnostic=read(w/'diagnostics.json');domain=read(w/'domain_validation.json');assert domain['status']=='passed'
    rows=[r for r in a['comparisons'] if r['engine']=='sionna' and r['shadow_refined'] and r['shadow_refined']['complex_rms'] is not None];worst=max(rows,key=lambda r:r['shadow_refined']['complex_rms'])
    summary=table(['Population','Workflow','Material','Channels / shadow','Ray shadow RMS','BIE32 shadow RMS','Corrected shadow RMS','Corrected total RMS'],[(r['campaign'],r['engine'],r['material'],f'{r["channels"]} / {r["shadow_channels"]}',pc(r['shadow_ray']['complex_rms']),pc(r['shadow_standard']['complex_rms']),pc(r['shadow_refined']['complex_rms']),pc(r['refined']['complex_rms'])) for r in a['summary']])
    control=table(['Mode q','BIE16','BIE32','BIE48','BIE64','2 BIE32 − BIE16','Observed order 16/32/64'],[(f'{r["q"][0]:.3f}+{r["q"][1]:.3f}i',*[pc(r['relative_errors'][k]) for k in ('bie16','bie32','bie48','bie64','rich16_32')],f'{r["self_convergence_order"]:.3f}') for r in probes['rows']])
    nuisance=table(['Mode q','Panel quadrature 12→24','Unstretched boundary 3→5 λ','Absorbing tail 3→5 λ'],[(f'{r["q"][0]:.3f}',pc(r['quadrature_change']),pc(r['core_change']),pc(r['tail_change'])) for r in probes['rows']])
    reference=table(['Population','Material','Full-field reference change','Shadow reference change'],[(r['campaign'],r['material'],pc(r['full_change']),pc(r['shadow_change'])) for r in a['reference_checks']])
    groups=table(['Group','BIE32 shadow RMS','Corrected shadow RMS','Reference refinement','Corrected phase median / p95'],[(r['name'],pc(r['shadow_standard']['complex_rms']),pc(r['shadow_refined']['complex_rms']),pc(r['reference_shadow_change']['complex_rms']),f'{r["shadow_refined"]["phase_median_abs_deg"]:.3f}° / {r["shadow_refined"]["phase_p95_abs_deg"]:.3f}°') for r in rows])
    for name in ('analysis.json','study_plan.json','diagnostics.json','probe_analysis.json','domain_validation.json'):shutil.copyfile(w/name,out/name)
    page=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Weak dielectric polarization: spatial convergence</title>
<style>body{{font:17px/1.65 system-ui;background:#08131d;color:#dce8f0;max-width:1220px;margin:35px auto;padding:0 24px}}h1,h2{{color:#fff;line-height:1.2}}h1{{font-size:38px}}h2{{margin-top:38px}}a{{color:#64d6e8}}table{{width:100%;border-collapse:collapse;font-size:14px;margin:20px 0}}th,td{{padding:9px;border:1px solid #334a5c;text-align:left}}th{{background:#193345}}video{{width:100%;border-radius:12px}}.box{{padding:18px 24px;background:#122b3b;border-left:4px solid #55d4bd}}pre{{white-space:pre-wrap;overflow-wrap:anywhere;background:#122b3b;padding:16px}}details{{overflow:auto}}</style><body>
<p><a href="../../../../index.html">All results</a> · <a href="../dielectric3d_refinement/index.html">Previous 18.71% result</a></p>
<h1>Weak dielectric polarization: resolving the spatial error</h1>
<div class="box"><p><strong>The targeted weak group now differs from the finer independent Maxwell reference by {pc(weak['corrected_vs_fem64']['complex_rms'])}, versus {pc(weak['baseline_vs_fem64']['complex_rms'])} for BIE32.</strong> The preceding report measured 18.7104% against FEM48; the numbers here use FEM64 for both before and after. Corrected median / 95th-percentile absolute phase differences are {weak['corrected_vs_fem64']['phase_median_abs_deg']:.3f}° / {weak['corrected_vs_fem64']['phase_p95_abs_deg']:.3f}°.</p><p>This repairs the numerical discretization of the optional shared full-wave companion. Sionna and DiffeRT native UTD outputs are retained. No field, phase or material parameter was fitted to Maxwell data.</p></div>
<h2>Regenerated comparison</h2><video controls preload="metadata" poster="previews/frame_0361.png" src="Sionna_vs_DiffeRT_Dielectric3D_Weak.mp4"></video>
<p>60 seconds · 1600 × 900 · 24 fps · <a href="Sionna_vs_DiffeRT_Dielectric3D_Weak.mp4">MP4</a> · <a href="Dielectric3D_Weak_Comparison.blend">Blender timeline</a>. White is independent FEM; gray is the original BIE32 field; color is the labelled mode. The same companion serves both engine workflows. Native paths are shown only as geometric context. Each phase plot declares its scale.</p>
<h2>Why the weak channel magnified the error</h2>
<p>The target is a y-oriented electric dipole received on z, εr≈7.1−1.1i, source azimuth 71.25°, receiver azimuths 255°, 260°, 265°, and height difference 0.45 λ. The analytic free-space term and spectral contributions cancel strongly: the sum of their magnitudes is {min(diagnostic['cancellation_ratio']):.1f}–{max(diagnostic['cancellation_ratio']):.1f} times the final field magnitude. A few percent of spatial error in the individual propagating modes can therefore become a much larger relative error in this weak total field.</p>
<p>Archived BIE/FEM mode comparisons locate almost all of the discrepancy below q=7, principally q=0–4. Four representative modes were selected for independent controls. They cover the dominant low-q contribution and the approach to the vacuum transition. The following errors use separately solved FEM64 fields at the same q, source and receiver ports.</p>{control}
<p>The dominant modes show approximately first-order panel convergence. The higher-q controls converge more slowly, so this is not a uniform first-order theorem. Increasing panel quadrature or extending the absorbing boundary changes these modes by orders of magnitude less than the BIE32/FEM discrepancy:</p>{nuisance}
<h2>Correction and acceptance</h2>
<pre>F(h) = F(0) + c h + higher-order terms
F_corrected = 2 F(h) − F(2h) = 2 BIE32 − BIE16</pre>
<p>The weights follow from the resolution ratio and assumed leading order. They are fixed for every material, source, receiver and polarization. No mode-specific correction, complex gain, phase offset or completed-channel reciprocity average is used. Since the weights sum to one, the analytic free-space term is preserved mathematically. Both component solves must match physical inputs, spectral settings and source hashes. The whole batch is geometry-validated before either solve begins.</p>
<p>The candidate and a new 324-channel holdout were frozen before their FEM results existed. New materials are εr≈4.4−0.65i and 6.4−0.9i; source radius 1.65 λ and azimuth 64°, receiver radius 2.15 λ, three receiver heights, all nine Cartesian dipole pairs, and ±0.01° boundary stencils. Recorded gates require the targeted group below 5% and at least a threefold improvement, each material/aggregate shadow norm below 5%, no previous-population degradation beyond 0.2 percentage points, raw reciprocity below 1%, and boundary-span discrepancy below 0.1%. <a href="study_plan.json">Frozen plan and hashes</a>.</p>
<h2>Complete population results</h2>{summary}
<p>Primary and previous holdout populations retain their prior fine references; the dedicated three-port target additionally receives FEM64 and independent spectral-refinement checks below. Complex RMS is √(Σ|F−Fref|²/Σ|Fref|²), without rescaling. Shadow masks exclude ±0.02° around transitions. Phase is excluded at numerical nulls. Counts are physical channels, not multiplied by the two workflows.</p>
<p><strong>Remaining worst group:</strong> <code>{worst['name']}</code>, corrected shadow RMS {pc(worst['shadow_refined']['complex_rms'])}, BIE32 {pc(worst['shadow_standard']['complex_rms'])}, and reference-refinement change {pc(worst['reference_shadow_change']['complex_rms'])}. Passing material averages does not guarantee that every weak port is below 5%.</p>
<p>Individual weak groups can worsen against the selected finite reference even while the material-wide norms improve. The complete before/after table and each group's reference sensitivity are retained; no per-port switching or calibration was used to optimize these comparisons.</p>
<details><summary>Every non-null shadow polarization group</summary>{groups}</details>
<h2>Independent Maxwell refinement</h2>
<p>At the targeted weak ports, FEM48→FEM64 at fixed spectral order 8 changes the field by {pc(weak['reference_spatial_change'])}. Increasing spectral order 8→12 at fixed FEM48 changes it by {pc(weak['reference_spectral_change'])}. The FEM code assembles coupled finite-element volume equations; it contains no BIE or UTD operator. Identical cached mode reuse is checksummed and documented. Independent analytic plane, free-space, PEC and domain controls from the earlier study remain available in its evidence.</p>{reference}
<p>A fresh independent FEM domain check enlarges the unstretched half-domain from 2.5 to 3.5 λ at fixed FEM48 grid spacing and PML thickness. The largest change across the four selected weak-port modes is {pc(max(r['relative_mode_change'] for r in domain['rows']))}. This is a targeted mode-level sensitivity check, not a full-field error bound. <a href="domain_validation.json">All domain controls</a>.</p>
<p>The primary reference comparisons vary grid and spectral order together; prior and new holdout comparisons vary grid at fixed order 8. These are empirical sensitivity checks, not rigorous error bounds. Agreement at or below reference-refinement sensitivity does not establish that absolute physical accuracy. Both Maxwell solvers are project implementations, independent of the ray engines but not third-party certification.</p>
<h2>Reciprocity and boundaries</h2>
<p>Separately solved source/reversed-source dyads have raw reciprocity discrepancy {pc(a['reciprocity']['relative_error'])}; no averaging is applied. All {a['boundaries']['stencils']} old/new boundary stencils are finite. Maximum normalized boundary-span discrepancy is {pc(a['boundaries']['maximum_span_error'])}; maximum complete-stencil field RMS discrepancy is {pc(a['boundaries']['maximum_field_rms'])}. A small span discrepancy is a continuity diagnostic, not a guarantee of small absolute field error.</p>
<h2>Workflow, geometry guards and cost</h2>
<p>The default companion uses the converged mode after the declared checks pass. The original single-resolution option is retained:</p>
<pre>.\\Compare_Dielectric3D_Wedge.ps1
.\\Compare_Dielectric3D_Wedge.ps1 -Accuracy standard
.\\Regenerate_Dielectric3D_Weak_Animation.ps1</pre>
<p>The companion remains restricted to the declared infinite solid dielectric quadrant, exact canonical faces/edge, supported electric point-dipole orientations, loss range and port envelope. Changed or additional obstacles, arrays and unsupported interactions are rejected before solving. Native Blender geometry/visibility checks continue to handle general scenes. The new calculation is more expensive than BIE32 because it adds a BIE16 solve, and remains much more expensive than UTD. Cached numerical steps are reused only with matching source and input hashes.</p>
<p>The returned field is single-frequency and has no ray-delay decomposition or end-to-end automatic-differentiation graph. The total shadow field can include transmission through the solid volume; it is not an isolated native diffraction coefficient. No installed runtime helper, engine or Blender extension file is replaced.</p>
<h2>Verification and reproducibility</h2>
<p><a href="verification.json">Final verification</a> · <a href="native_workflow_health.json">Native Blender check</a> · <a href="reciprocal_blender.json">Reciprocal Blender check</a> · <a href="video_validation.json">Video decode / timeline reopen</a> · <a href="dielectric3d_weak_evidence.zip">Checksummed numerical and source evidence</a> · <a href="analysis.json">All measured fields</a> · <a href="../../../../Compare_Dielectric3D_Wedge.ps1">Comparison launcher</a>.</p>
<p>Research scripts and reproduction commands are in <code>work/github-update/differt-bridge/docs/dielectric3d-weak.md</code>. The evidence retains the frozen candidate, all controls, FEM refinements, before/after field comparisons, raw engine receipts, and validation checks. Previous evidence remains linked above. Temporary PNG sequences are deleted only after decode, content-hash and image-quality verification.</p>
<h2>Primary-source context</h2>
<p><a href="https://www.nist.gov/publications/scattering-dielectric-wedge-oblique-incidence-0">NIST's oblique-incidence dielectric-wedge work</a> describes coupled integral equations and edge-field behavior; <a href="https://www.nist.gov/publications/numerical-experiments-scattering-dielectric-wedge">its numerical study</a> discusses the integration difficulties associated with singular fields. These motivate the resolution controls, not the numerical correction coefficients. <a href="https://docs.scipy.org/doc/scipy/tutorial/integrate.html">SciPy's integration documentation</a> explains why finite quadrature samples alone cannot certify an arbitrary integral; the independent spectral-order check addresses that limitation for this target.</p></body></html>'''
    (out/'index.html').write_text(page,encoding='utf-8');print(out/'index.html')

if __name__=='__main__':main(Path(sys.argv[1]).resolve())
